            if not every and reg_ids is None:
                if changed:
                    jd.rollup_status(store, False)
                    jd.save_goals(sid, store)
                    _mark_views_dirty()
                continue
            # RESTART-ORPHAN reconciliation (the user 2026-08-24): a kernel/backend restart kills
