        err, tid = _comment_create(sid, str(msg["uuid"]), str(msg["exact"]), str(msg["text"]),
                                   name=str(msg.get("name") or ""),
                                   model=str(msg.get("model") or ""), effort=str(msg.get("effort") or ""),
                                   color=str(msg.get("color") or ""))
